const knowledgeAutomationHasHumanDisposition = `-- name: KnowledgeAutomationHasHumanDisposition :one
SELECT EXISTS (
    SELECT 1 FROM collaboration_knowledge_candidate
    WHERE source_issue_id=$1 AND target_project_id=$2
      AND target_workspace_id=$3 AND proposal_origin='automation' AND decision_origin='human'
      AND state IN ('withdrawn','rejected','superseded')
      AND replace(replace(content,E'\r\n',E'\n'),E'\r',E'\n')=replace(replace($4::text,E'\r\n',E'\n'),E'\r',E'\n')
      AND applicability=$5::jsonb
)::boolean
`

type KnowledgeAutomationHasHumanDispositionParams struct {
	SourceIssueID pgtype.UUID `json:"source_issue_id"`
	ProjectID     pgtype.UUID `json:"project_id"`
	WorkspaceID   pgtype.UUID `json:"workspace_id"`
	Content       string      `json:"content"`
	Applicability []byte      `json:"applicability"`
}

// A fresh candidate ID must not bypass a human disposition of the same
// automatically proposed knowledge. This examines retained metadata in-place;
// no historical rejected/withdrawn text is sent back to the model.
func (q *Queries) KnowledgeAutomationHasHumanDisposition(ctx context.Context, arg KnowledgeAutomationHasHumanDispositionParams) (bool, error) {
	row := q.db.QueryRow(ctx, knowledgeAutomationHasHumanDisposition,
		arg.SourceIssueID,
		arg.ProjectID,
		arg.WorkspaceID,
		arg.Content,
		arg.Applicability,
	)
	var column_1 bool
	err := row.Scan(&column_1)
	return column_1, err
}

